{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>{{BUSINESS_NAME}} — {{TAGLINE}}</title>
  <meta name="description" content="Private psychotherapy with {{THERAPIST_NAME}} — compassionate, practical support for anxiety, trauma, relationships, and life transitions in {{CITY}}, {{STATE}}.">
  <link rel="stylesheet" href="assets/css/styles.css">
</head>
<body>
  <header class="site-header">
    <div class="container header-inner">
      <a class="brand" href="/">{{BUSINESS_NAME}}</a>
      <nav class="nav" aria-label="Main navigation">
        <button id="menuToggle" class="menu-toggle" aria-expanded="false">Menu</button>
        <ul id="mainNav" class="nav-list">
          <li><a href="/">Home</a></li>
          <li><a href="about.html">About</a></li>
          <li><a href="specialties.html">Work With Me</a></li>
          <li><a href="approach.html">Approach</a></li>
          <li><a href="fees.html">Fees</a></li>
          <li><a href="faq.html">Support</a></li>
          <li><a href="book.html" class="cta">{{PRIMARY_CTA_LABEL}}</a></li>
        </ul>
      </nav>
    </div>
  </header>

  <main>
    <!-- HERO -->
    <section id="hero" class="hero container">
      <div class="hero-content">
        <h1 class="hero-title">{{TAGLINE}}</h1>
        <p class="hero-sub">Private, evidence-informed therapy with {{THERAPIST_NAME}} ({{LICENSE}}). Practical tools, steady support — for anxiety, trauma, relationships and life transitions.</p>
        <div class="hero-actions">
          <a href="{{PRIMARY_CTA_URL}}" class="btn primary">{{PRIMARY_CTA_LABEL}}</a>
          <a href="contact.html" class="btn ghost">Contact</a>
        </div>
        <p class="local">Serving {{CITY}}, {{STATE}} — telehealth and limited in-person availability.</p>
      </div>
      <div class="hero-art"><img src="assets/img/hero.svg" alt="Illustration representing calm and focus"></div>
    </section>

    <!-- STORY -->
    <section id="story" class="container card story">
      <div class="story-inner">
        <img class="avatar" src="assets/img/avatar.svg" alt="Portrait illustration of {{THERAPIST_NAME}}">
        <div>
          <h2>How I work</h2>
          <p>I bring a warm, practical approach grounded in evidence-based methods. I meet you where you are — whether you are navigating anxiety, healing from past hurt, repairing relationships, or reorienting your life after a major change. Therapy with me is collaborative: we set clear goals, practice skills between sessions, and review progress together.</p>
          <p class="small">Confidentiality is central: sessions are private and protected. I will explain limits to confidentiality, my scope of practice, and provide referrals if needs fall outside therapy. If you are in crisis or danger, please call local emergency services or a crisis line immediately.</p>
        </div>
      </div>
    </section>

    <!-- FRAMEWORK -->
    <section id="framework" class="container framework">
      <h2>A simple framework I use</h2>
      <p class="lede">A practical, four-part rhythm to guide work in therapy.</p>
      <ol class="steps">
        <li><strong>Listen & map:</strong> Clarify patterns and priorities with empathy and curiosity.</li>
        <li><strong>Skill-build:</strong> Learn tools for managing distress and building new habits.</li>
        <li><strong>Practice:</strong> Apply strategies between sessions in real-life situations.</li>
        <li><strong>Reflect & adjust:</strong> Review progress and adapt plans as needed.</li>
      </ol>
    </section>

    <!-- PROGRAMS -->
    <section id="programs" class="container programs">
      <h2>Paths & programs</h2>
      <p class="lede">Short-term pathways and ongoing care tailored to common goals.</p>
      <div class="grid">
        <article class="card">
          <h3>Start-Up Series</h3>
          <p>Six sessions to build immediate coping tools for anxiety and overwhelm. A clear, time-limited plan to get you moving.</p>
          <a href="fees.html#startup" class="link">Learn more</a>
        </article>
        <article class="card">
          <h3>Core Work</h3>
          <p>Weekly sessions focused on deeper patterns — trauma processing, relationship work, and self-regulation skills.</p>
          <a href="fees.html#core" class="link">Learn more</a>
        </article>
        <article class="card">
          <h3>Intensive Support</h3>
          <p>Short, concentrated sessions over several weeks for transitions, crisis recovery, or sudden life changes.</p>
          <a href="fees.html#intensive" class="link">Learn more</a>
        </article>
      </div>
    </section>

    <!-- PRICING / FEES -->
    <section id="pricing" class="container pricing">
      <h2>Fees & availability</h2>
      <p class="lede">I offer transparent fees and a few flexible options. Sliding scale spots may be available; inquire by phone or email.</p>
      <div class="pricing-grid">
        <div class="price-card">
          <h4>Intro Session</h4>
          <p class="amount">$160 — 50 minutes</p>
          <p class="muted">A focused first session to assess fit and goals.</p>
        </div>
        <div class="price-card featured">
          <h4>Standard Session</h4>
          <p class="amount">$160 — 50 minutes</p>
          <p class="muted">Weekly or biweekly sessions depending on your plan.</p>
        </div>
        <div class="price-card">
          <h4>Extended/Intensive</h4>
          <p class="amount">$220 — 75 minutes</p>
          <p class="muted">For more complex work or concentrated blocks.</p>
        </div>
      </div>
      <p class="small">Insurance: {{BUSINESS_NAME}} does not currently bill insurance directly. I can provide receipts for out-of-network reimbursement. All financial arrangements are discussed confidentially.</p>
    </section>

    <!-- TESTIMONIALS -->
    <section id="testimonials" class="container testimonials">
      <h2>Feedback from clients</h2>
      <p class="lede">Words from people who have worked with me — anonymized for privacy.</p>
      <div class="test-grid">
        <blockquote class="quote">"I learned simple practices that helped me sleep and feel steadier. {{THERAPIST_NAME}} was patient and practical." <cite>— J., 34</cite></blockquote>
        <blockquote class="quote">"A safe space to make sense of difficult memories and find a path forward." <cite>— A., 41</cite></blockquote>
      </div>
    </section>

    <!-- CTA -->
    <section id="cta" class="container cta">
      <div class="cta-inner">
        <h2>Ready to begin?</h2>
        <p>Start with a conversation to see if we’re a good fit. I offer telehealth and limited in-person appointments.</p>
        <div>
          <a href="{{PRIMARY_CTA_URL}}" class="btn primary">{{PRIMARY_CTA_LABEL}}</a>
          <a href="book.html" class="btn ghost">Schedule</a>
        </div>
      </div>
    </section>
  </main>

  <footer class="site-footer">
    <div class="container footer-inner">
      <div>
        <p class="brand-footer">{{BUSINESS_NAME}} — {{THERAPIST_NAME}} ({{LICENSE}})</p>
        <p class="muted">Phone: {{PHONE}} • Email: <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></p>
      </div>
      <div class="footer-notes">
        <p class="small">Confidentiality & privacy: Sessions are confidential and clinical records are kept private within legal limits. I will discuss limits to confidentiality, including safety exceptions, in our first meeting.</p>
        <p class="small">Scope & boundaries: I provide psychotherapy and am not able to provide emergency services. If you are in crisis or at immediate risk, please call local emergency services or a crisis hotline.</p>
      </div>
    </div>
  </footer>

  <script src="assets/js/main.js"></script>
</body>
</html>"} 
